                    entry.entry_info().set_policy_gen(gen);
                    if eviction_state.is_notifier_enabled() {
                        eviction_state.notify_entry_removal(key, &entry, RemovalCause::Size);
                    }
                    eviction_state.counters.incr_eviction_count();
